<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVariable\Domain\Event;

use Override;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\TemplateVariable;
use Civi\Lughauth\Shared\Event\PublicEvent;

class TemplateVariableCreateEvent extends TemplateVariableEvent implements PublicEvent
{
    public function __construct(
        TemplateVariable $payload
    ) {
        parent::__construct($payload);
    }
    #[Override]
    public function eventType(): string
    {
        return 'template-variable.create';
    }
    #[Override]
    public function schemaVersion(): string
    {
        return 'v1';
    }
    #[Override]
    public function payload(): array
    {
        return $this->payload->asPublicJson();
    }
    #[Override]
    public function original(): array
    {
        return [];
    }
}
